"""Standalone HTML report with real application screenshots and QA evidence."""
from pathlib import Path
import json
from datetime import datetime
from zoneinfo import ZoneInfo
from html import escape

root=Path(__file__).resolve().parent.parent;out=root/'reports/resources-update'
state=json.loads((out/'verified-state.json').read_text(encoding='utf-8-sig'))
vm=json.loads((out/'vm-check.json').read_text(encoding='utf-8-sig'))
assert vm['status']=='passed' and vm['verification']['passed']
now=datetime.now(ZoneInfo('Asia/Seoul'));start=datetime(2026,10,24,20,21,8,tzinfo=ZoneInfo('Asia/Seoul'));elapsed=int((now-start).total_seconds())
rows=''.join(f'<tr><td><img class="icon" src="../../src/web/resource-icons/{p["icon"]}.svg">{escape(p["name"])}</td><td>{escape(p["description"])}</td><td>{"설치됨" if p["installed"] else "설치 근거 없음"}</td></tr>' for p in state['catalog'])
html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>모아 · 도구와 스킬 대시보드</title><link rel="icon" href="../../docs/assets/moa-logo.png"><style>
*{box-sizing:border-box}body{margin:0;background:#faf7f3;color:#352c28;font:15px/1.8 system-ui,sans-serif;letter-spacing:-.025em}main{max-width:1100px;margin:auto;padding:40px 26px 75px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eadfd7;padding-bottom:20px}header img{width:116px;height:60px;object-fit:contain}.eyebrow{font-size:11px;letter-spacing:.15em;color:#b7664b}h1{font-size:40px;line-height:1.4;letter-spacing:-.06em;margin:34px 0 10px}h2{font-size:23px;margin:0 0 12px}h3{font-size:15px;margin:0 0 7px}p{margin:0 0 14px}.muted,small,figcaption{color:#96867a}a{color:#ab573b;text-underline-offset:4px}section{background:#fff;border:1px solid #e9dfd6;border-radius:19px;padding:28px;margin:22px 0}figure{margin:18px 0 0}figure img{display:block;width:100%;border-radius:12px;border:1px solid #eee5dc}figcaption{font-size:12px;margin-top:8px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.metrics>div{padding:19px;border-radius:13px;background:#f0e7dd}.metrics strong{display:block;font-size:25px;line-height:1.5}.metrics span{font-size:11px;color:#947c6a}.row{display:grid;grid-template-columns:1fr 1fr;gap:20px}.row section{margin:0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #eee5dd;padding:12px 9px;text-align:left;vertical-align:middle}th{color:#a18470;font-weight:500}.icon{width:23px;height:23px;object-fit:contain;vertical-align:middle;margin-right:10px}.notice{padding:17px 20px;background:#f7f0e7;border-radius:11px;font-size:13px}.evidence{font-size:12px;color:#897a6e}details{padding:18px 0}summary{cursor:pointer;color:#9b6f59;font-size:13px}details figure{max-width:850px}code{background:#f3eee8;padding:2px 5px;border-radius:4px;font-size:12px}footer{font-size:12px;color:#958478;margin-top:28px}.nav{display:flex;flex-wrap:wrap;gap:18px;margin:20px 0;font-size:12px}@media(max-width:650px){main{padding:24px 15px}.row{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}section{padding:20px}h1{font-size:29px}table{font-size:11px}}
</style></head><body><main><header><img src="../../docs/assets/moa-logo.png" alt="모아"><span class="eyebrow">WORKSPACE UPDATE · 2026.10.24</span></header><h1>필요한 도구부터 팀의 원칙까지,<br>한곳에서 준비합니다.</h1><p class="muted">프로그램 카탈로그 · 설치 상태 · 스킬 추가 · 전역·봇별 지시 사항</p><nav class="nav"><a href="#programs">프로그램</a><a href="#skills">스킬</a><a href="#instructions">지시 사항</a><a href="#qa">검증 결과</a><a href="http://127.0.0.1:8765/#resources">대시보드 열기 ↗</a></nav><div class="metrics"><div><strong>10개</strong><span>설치 전에도 보이는 프로그램</span></div><div><strong>6개</strong><span>기본 스킬과 직접 추가 기능</span></div><div><strong>248개</strong><span>실제 Windows 설치 기록 확인</span></div><div><strong>271.92초</strong><span>실제 Slack·VM 재검증 통과</span></div></div>
<section id="programs"><h2>01 · 프로그램 준비와 설치</h2><p>프로그램마다 아이콘·짧은 설명·설치 상태·공식 사이트를 표시합니다. 설치 전에도 전체 카탈로그가 보이며 이름과 용도로 검색하거나 설치됨·미설치로 걸러볼 수 있습니다. 개별 설치와 선택 항목 일괄 설치를 지원합니다.</p><figure><img src="programs.jpg" alt="실제 모아 프로그램 카탈로그"><figcaption>실제 실행 화면. Git은 Windows 설치 기록, Node.js는 실행 파일 경로로 확인했습니다.</figcaption></figure><details><summary>프로그램 10개와 현재 확인 결과</summary><table><tr><th>프로그램</th><th>용도</th><th>이 PC 확인 결과</th></tr>__ROWS__</table></details><p class="notice">Windows WinGet에 등록된 정확한 패키지 ID로 사용자 범위 설치를 요청합니다. 관리자 권한·자동 재부팅·임의 URL 설치를 실행하지 않습니다. 사용자 범위 설치가 지원되지 않는 프로그램은 설치 실패 기록과 공식 사이트를 확인해야 합니다. 이번 검증에서 새 Windows 프로그램을 실제 설치하지는 않았습니다.</p><p class="evidence">설치 목록은 Windows 레지스트리와 PATH 실행 파일 근거로 확인합니다. 설치 프로세스 종료 코드만으로 성공을 선언하지 않으며, 실행 파일이나 설치 기록을 다시 확인합니다. 수집된 브랜드 SVG와 자체 벡터 아이콘은 프로젝트 안에 저장되어 설치 여부와 관계없이 표시됩니다.</p></section>
<section><h2>02 · 일을 맡기기 전에 준비 후보 확인</h2><p>작업 내용을 적고 <strong>필요한 프로그램·스킬 미리 보기</strong>를 누르면 키워드 기준의 후보를 표시합니다. 추천 자체를 필수 설치로 단정하지 않으며, PC와 실제 VM의 준비 상태를 구분합니다.</p><figure><img src="preflight.jpg" alt="실제 작업 전 프로그램·스킬 추천"><figcaption>입력·추천 기능만 실행했습니다. 화면의 CSV 예시 작업을 새로 접수하거나 실행한 것은 아닙니다.</figcaption></figure></section>
<section id="skills"><h2>03 · 스킬 추가와 팀원 배정</h2><p>미니멀 웹 디자인, 실행 기반 QA, Python 자동화, 팀 협업, 이미지 작업, 근거 중심 조사 스킬을 제공합니다. 각 항목에 설명과 아이콘을 표시하며 직접 이름·설명·지침을 작성하거나 Markdown 파일로 지침을 가져올 수 있습니다. 팀원을 선택하면 해당 봇에게만 적용됩니다.</p><figure><img src="skills.jpg" alt="스킬 카탈로그와 실행 기반 QA 추가 상태"><figcaption>실행 기반 QA 스킬을 실제로 추가하고 새로고침 후 유지되는 것을 확인했습니다.</figcaption></figure><p class="notice">스킬은 작업 방법을 담은 지침 묶음입니다. 스킬 추가 자체가 인터넷 검색·이미지 인식·새 실행 도구를 제공한다는 뜻은 아닙니다. 실제 제공되는 도구의 범위 안에서 적용됩니다.</p></section>
<section id="instructions"><h2>04 · 전역·봇별 지시 사항</h2><p>공통 지침과 개별 봇 지침을 별도 저장합니다. 기존 팀원 이름·역할 설정과 연결되며, 새 작업에 지침과 활성 스킬을 저장해 진행 중인 작업의 기준이 뒤바뀌지 않도록 했습니다. 봇이 작업 중 새로 요청한 스킬도 요청 당시 내용을 기록합니다.</p><figure><img src="instructions.jpg" alt="전역 지시 사항과 봇별 지시 사항 편집"><figcaption>기존 지침을 임의로 새 내용으로 바꾸지 않았습니다. 저장·전달·이전 작업 기준 유지 여부는 격리 검사로 검증했습니다.</figcaption></figure></section>
<div class="row"><section><h2>05 · 봇이 필요할 때 준비</h2><p>자동 준비 설정에서 프로그램 허용 목록과 설치 조건을 한 번 저장하면, 봇의 프로그램 요청을 검사해 설치 대기열로 보냅니다. 등록된 스킬은 자동 추가 설정과 팀원 배정을 확인해 반영합니다.</p><p>설치·봇 요청 기록에서 누가 어떤 대상에 무엇을 요청했는지 확인할 수 있습니다. 설치 불가·허용 필요 상태는 작업에 이유를 남기고, Slack 협업 작업이면 사용자에게 준비 필요 메시지를 보냅니다.</p></section><section><h2>06 · 실제 VM은 별도로 확인</h2><p>실제 QEMU VM에서 <code>command -v</code>로 카탈로그 프로그램의 실행 파일을 확인했습니다. 현재 VM에는 Python·Git 실행 파일이 없고 네트워크가 꺼져 있습니다.</p><p>VM 설치 예약은 다음 VM 작업이 사용권을 얻었을 때 처리합니다. 현재 번들 Tiny Core는 등록된 Python·Git 확장 패키지를 대상으로 합니다. 네트워크가 꺼져 있으면 보류하며 자동으로 켜지 않습니다. 현재 환경에서 VM 패키지 다운로드 설치 완료를 검증한 것은 아닙니다.</p></section></div>
<section id="qa"><h2>07 · 실제 실행과 재검증</h2><table><tr><th>검증 항목</th><th>결과와 범위</th></tr><tr><td>Windows 프로그램 목록</td><td>실제 설치 기록 248개, 카탈로그 10개 중 Git·Node.js 확인</td></tr><tr><td>프로그램 설치 경로</td><td>정확한 패키지 ID·허용 목록·약관·중복 방지·재시작 시 자동 재실행 방지·설치 근거 재확인 검사. 새 Windows 프로그램 설치는 수행하지 않음</td></tr><tr><td>스킬·지침</td><td>실제 UI에서 QA 스킬 추가·유지 확인. 전역·봇별 지침 및 스킬 배정·고정 저장·모델의 스킬 요청 경로는 격리 검사</td></tr><tr><td>관련 검사</td><td>Python 76건 통과 · UI 11묶음 통과 · JavaScript/Python 구문 검사와 git diff --check 통과</td></tr><tr><td>실제 Slack·모델·VM</td><td>작업 __TASK__ 완료, 271.92초. 수신 이벤트 3건·다운로드 이미지 3개 확인. 실제 VM 파일 생성·독립 명령 검증·ZIP 안의 파일 바이트 대조 통과</td></tr></table><figure><img src="actual-vm.png" alt="실제 VM에서 ready.txt를 독립 검증한 화면"><figcaption>실제 QEMU VM 화면. test 명령과 REVIEW_PASS 출력은 실제 게스트 실행 결과입니다.</figcaption></figure><details><summary>검증 중 수정한 문제 1건</summary><p>프로그램 확인 명령의 중첩 따옴표가 터미널 입력 길이를 넘겨 첫 검증이 실패했습니다. 입력 후 화면과 직렬 로그에서 실행 시작 표식이 없는 것을 확인했습니다. 확인 명령을 짧은 반복문으로 바꾸고 최종 입력 길이를 검사하는 보호를 추가했습니다. 이후 새 작업의 실제 재검증이 통과했습니다. 최초 실패 기록도 보존했습니다.</p><figure><img src="fixed-input-failure.png" alt="수정 전 긴 입력이 잘린 VM 화면"><figcaption>수정 전 실패 증거입니다. 실패를 통과로 바꾸지 않고 새 검증으로 대조했습니다.</figcaption></figure></details><p class="evidence"><a href="unit-checks.log">Python 검사 로그</a> · <a href="ui-checks.log">UI 검사 로그</a> · <a href="vm-check.json">실제 VM 검증 결과</a> · <a href="verified-state.json">프로그램·스킬·VM 확인 근거</a> · <a href="real-vm-check.log">실제 통합 검증 로그</a></p></section>
<section><h2>바로 사용하는 방법</h2><p>모아 사이드바의 <strong>도구와 스킬</strong>을 여세요. 프로그램 자동 설치는 <strong>봇 자동 준비 설정</strong>에서 허용 목록과 설치 조건을 저장한 뒤 사용할 수 있습니다. 스킬 자동 추가는 기본으로 켜져 있습니다. 전역·봇별 지침은 지시 사항 탭에서 작성하시면 됩니다.</p><p><a href="http://127.0.0.1:8765/#resources">대시보드 열기 →</a> · <a href="http://127.0.0.1:8765/#docs/resources">앱 안의 사용 가이드 →</a></p><p class="evidence">공식 근거: <a href="https://learn.microsoft.com/en-us/windows/package-manager/winget/install">Microsoft WinGet 설치 옵션</a> · <a href="https://wiki.tinycorelinux.net/doku.php?id=wiki%3Ainstall_apps">Tiny Core 확장 설치</a> · <a href="https://github.com/devicons/devicon/tree/v2.16.0">Devicon 고정 버전</a>. 브랜드 아이콘의 MIT 라이선스 원문을 소스에 함께 보관했습니다.</p></section><footer>제안 시간: 35~60분<br>실제 정리 완료: __TIME__ KST · 소요 __ELAPSED__<br>XERJ: 미사용 — 제공 도구·검색 스크립트 없음, rg로 대체</footer></main></body></html>'''
html=html.replace('__ROWS__',rows).replace('__TASK__',vm['task_id']).replace('__TIME__',now.strftime('%Y-%m-%d %H:%M:%S')).replace('__ELAPSED__',f'{elapsed//60}분 {elapsed%60}초')
(out/'index.html').write_text(html,encoding='utf-8')
for name in ('programs.jpg','skills.jpg','instructions.jpg','preflight.jpg','actual-vm.png','fixed-input-failure.png','ui-checks.log','unit-checks.log'):
    assert (out/name).is_file(),name
print(f'{now.isoformat()} elapsed={elapsed}s; report and evidence files verified.')
